import{_ as a,o as r,c as o,a3 as s}from"./chunks/framework.1Y430-yj.js";const m=JSON.parse('{"title":"Task Board Rules","description":"","frontmatter":{"lang":"en-US","translationSource":{"title":"任务板公约","archivedAt":"2026-10-23T14:20:34.857Z","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=x92HMu2s9XkaihJaPQSJ6v","scope":"page"}},"headers":[],"relativePath":"logistics/src/page-x92HMu2s9XkaihJaPQSJ6v.md","filePath":"logistics/src/page-x92HMu2s9XkaihJaPQSJ6v.md","lastUpdated":null}'),t={name:"logistics/src/page-x92HMu2s9XkaihJaPQSJ6v.md"};function n(i,e,l,c,p,u){return r(),o("div",null,[...e[0]||(e[0]=[s('<div class="logistics-content"><span class="logistics-source-anchor" id="任务板公约" aria-hidden="true"></span><h1 id="task-board-rules" tabindex="-1">Task Board Rules <a class="header-anchor" href="#task-board-rules" aria-label="Permalink to &quot;Task Board Rules&quot;">​</a></h1><blockquote><p>Source page ID: <code>x92HMu2s9XkaihJaPQSJ6v</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=x92HMu2s9XkaihJaPQSJ6v" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>The task board is edited in the small “Talos-II Technical Development Bureau” (塔卫二技术开发局; provisional group-name translation) group. To contribute, first ask an existing member for admission: group owners/administrators or some frequent speakers in other groups. Not everyone can enter, but hard work or insight—and determination to prove yourself—can earn an opportunity.</p><p>If WeChat login or other Tencent Docs problems prevent editing access, explain in the QQ group, then request document access.</p><p>We trust editors have learned routine precautions from administrators. In summary: #1) Respect others&#39; work. #2) Think before entering content: copy or summarize? #3) Greater power means greater responsibility.</p><p>Generally, ongoing research belongs in task-board tasks; preliminary results belong in Group Members&#39; Results; only public-facing content belongs in the knowledge base. Put spaces around names. Prefer members&#39; group nicknames/common names; link nonmembers to their account homepage.</p><p>The main editors&#39; names follow, in no particular order, for copying:</p><p>jnk、言、Fatal Error A1012、SSnighter、madSUN、kokobird、[Ѵ. Ŋøᵰę]ᶱ、Cipolla_、斯改ms、Zirunwang、恒星泰斗、米斯雀、百亿亿亿亿、Orirock、盐酸利多卡因、xyIvneu_、c、桜夜天華、正交二叉树、Edward Kerman</p></div>',1)])])}const h=a(t,[["render",n]]);export{m as __pageData,h as default};
